type grainRNG struct{ r uint32 }

func (g *grainRNG) next(bits uint) int32 {
	r := g.r
	bit := (r ^ r>>1 ^ r>>3 ^ r>>12) & 1
	r = r>>1 | bit<<15
	g.r = r
	return int32(r>>(16-bits)) & (1<<bits - 1)
}

func round2s(x int32, n uint) int32 {
	if n == 0 {
		return x
	}
	return (x + 1<<(n-1)) >> n
}

// applyFilmGrain returns a copy of f with film grain added.
func applyFilmGrain(f *frame, g *filmGrain, s *SequenceHeader) *frame {
	out := cloneFrame(f)
	bd := uint(f.bitDepth)
	subX, subY := uint(s.SubX), uint(s.SubY)
	grainCenter := int32(128) << (bd - 8)
	grainMin := -grainCenter
	grainMax := int32(256)<<(bd-8) - 1 - grainCenter
	clip := func(v int32) int32 { return min(max(v, grainMin), grainMax) }

	// Generate the grain templates.
	var luma [73][82]int32
	rng := grainRNG{uint32(g.seed)}
	shift := uint(12 - int(bd) + g.grainScaleShift)
	for y := 0; y < 73; y++ {
		for x := 0; x < 82; x++ {
			v := int32(0)
			if g.numY > 0 {
				v = gaussianSequence[rng.next(11)]
			}
			luma[y][x] = round2s(v, shift)
		}
	}
	arShift := uint(g.arShift)
	lag := g.arLag
	for y := 3; y < 73; y++ {
		for x := 3; x < 82-3; x++ {
			sum, pos := int32(0), 0
		outer:
			for dr := -lag; dr <= 0; dr++ {
				for dc := -lag; dc <= lag; dc++ {
					if dr == 0 && dc == 0 {
						break outer
					}
					sum += luma[y+dr][x+dc] * int32(g.arY[pos])
					pos++
				}
			}
			luma[y][x] = clip(luma[y][x] + round2s(sum, arShift))
		}
	}
	chromaW, chromaH := 82, 73
	if subX != 0 {
		chromaW = 44
	}
	if subY != 0 {
		chromaH = 38
	}
	var cb, cr [73][82]int32
	gen := func(dst *[73][82]int32, seed uint32, on bool) {
		rng := grainRNG{uint32(g.seed) ^ seed}
		for y := 0; y < chromaH; y++ {
			for x := 0; x < chromaW; x++ {
				v := int32(0)
				if on {
					v = gaussianSequence[rng.next(11)]
				}
				dst[y][x] = round2s(v, shift)
			}
		}
	}
	gen(&cb, 0xb524, g.numCb > 0 || g.chromaScalingFromLuma)
	gen(&cr, 0x49d8, g.numCr > 0 || g.chromaScalingFromLuma)
	for y := 3; y < chromaH; y++ {
		for x := 3; x < chromaW-3; x++ {
			sum0, sum1, pos := int32(0), int32(0), 0
		outer2:
			for dr := -lag; dr <= 0; dr++ {
				for dc := -lag; dc <= lag; dc++ {
					c0, c1 := int32(g.arCb[pos]), int32(g.arCr[pos])
					if dr == 0 && dc == 0 {
						if g.numY > 0 {
							l := int32(0)
							lx := (x-3)<<subX + 3
							ly := (y-3)<<subY + 3
							for i := 0; i <= int(subY); i++ {
								for j := 0; j <= int(subX); j++ {
									l += luma[ly+i][lx+j]
								}
							}
							l = round2s(l, subX+subY)
							sum0 += l * c0
							sum1 += l * c1
						}
						break outer2
					}
					sum0 += c0 * cb[y+dr][x+dc]
					sum1 += c1 * cr[y+dr][x+dc]
					pos++
				}
			}
			if g.numCb > 0 || g.chromaScalingFromLuma {
				cb[y][x] = clip(cb[y][x] + round2s(sum0, arShift))
			}
			if g.numCr > 0 || g.chromaScalingFromLuma {
				cr[y][x] = clip(cr[y][x] + round2s(sum1, arShift))
			}
		}
	}

	// Scaling lookup tables.
	var lut [3][256]int32
	for p := 0; p < f.numPlanes; p++ {
		pts := g.pointY[:g.numY]
		switch {
		case p == 0 || g.chromaScalingFromLuma:
		case p == 1:
			pts = g.pointCb[:g.numCb]
		default:
			pts = g.pointCr[:g.numCr]
		}
		if len(pts) == 0 {
			continue
		}
		for i := 0; i < pts[0][0]; i++ {
			lut[p][i] = int32(pts[0][1])
		}
		for i := 0; i < len(pts)-1; i++ {
			dy := pts[i+1][1] - pts[i][1]
			dx := pts[i+1][0] - pts[i][0]
			delta := dy * ((65536 + dx>>1) / dx)
			for x := 0; x < dx; x++ {
				lut[p][pts[i][0]+x] = int32(pts[i][1] + (x*delta+32768)>>16)
			}
		}
		for i := pts[len(pts)-1][0]; i < 256; i++ {
			lut[p][i] = int32(pts[len(pts)-1][1])
		}
	}
	scaleLut := func(p int, index int32) int32 {
		sh := bd - 8
		x := index >> sh
		rem := index - x<<sh
		if bd == 8 || x == 255 {
			return lut[p][x]
		}
		start, end := lut[p][x], lut[p][x+1]
		return start + round2s((end-start)*rem, sh)
	}

	// Noise stripes of 32 luma rows, then the noise image.
	w, h := f.planes[0].w, f.planes[0].h
	numStripes := (h + 31) / 32
	stripeW := [3]int{w + 48, (w+1)>>1 + 32, (w+1)>>1 + 32}
	stripes := make([][3][]int32, numStripes)
	for i := range stripes {
		for p := 0; p < f.numPlanes; p++ {
			stripes[i][p] = make([]int32, 34*stripeW[p])
		}
	}
	lumaNum := 0
	for y := 0; y < (h+1)/2; y += 16 {
		rng := grainRNG{uint32(g.seed)}
		rng.r ^= uint32((lumaNum*37+178)&255) << 8
		rng.r ^= uint32((lumaNum*173 + 105) & 255)
		for x := 0; x < (w+1)/2; x += 16 {
			rnd := rng.next(8)
			offX, offY := int(rnd>>4), int(rnd&15)
			for p := 0; p < f.numPlanes; p++ {
				psx, psy := uint(0), uint(0)
				if p > 0 {
					psx, psy = subX, subY
				}
				pox, poy := 9+offX*2, 9+offY*2
				if psx != 0 {
					pox = 6 + offX
				}
				if psy != 0 {
					poy = 6 + offY
				}
				st := stripes[lumaNum][p]
				sw := stripeW[p]
				for i := 0; i < 34>>psy; i++ {
					for j := 0; j < 34>>psx; j++ {
						var gv int32
						switch p {
						case 0:
							gv = luma[poy+i][pox+j]
						case 1:
							gv = cb[poy+i][pox+j]
						default:
							gv = cr[poy+i][pox+j]
						}
						if psx == 0 {
							idx := i*sw + x*2 + j
							if j < 2 && g.overlap && x > 0 {
								old := st[idx]
								if j == 0 {
									gv = old*27 + gv*17
								} else {
									gv = old*17 + gv*27
								}
								gv = clip(round2s(gv, 5))
							}
							st[idx] = gv
						} else {
							idx := i*sw + x + j
							if j == 0 && g.overlap && x > 0 {
								gv = clip(round2s(st[idx]*23+gv*22, 5))
							}
							st[idx] = gv
						}
					}
				}
			}
		}
		lumaNum++
	}
	var noise [3][]int32
	for p := 0; p < f.numPlanes; p++ {
		psx, psy := uint(0), uint(0)
		if p > 0 {
			psx, psy = subX, subY
		}
		pw, ph := (w+int(psx))>>psx, (h+int(psy))>>psy
		noise[p] = make([]int32, pw*ph)
		sw := stripeW[p]
		for y := 0; y < ph; y++ {
			ln := y >> (5 - psy)
			i := y - ln<<(5-psy)
			for x := 0; x < pw; x++ {
				gv := stripes[ln][p][i*sw+x]
				if psy == 0 {
					if i < 2 && ln > 0 && g.overlap {
						old := stripes[ln-1][p][(i+32)*sw+x]
						if i == 0 {
							gv = old*27 + gv*17
						} else {
							gv = old*17 + gv*27
						}
						gv = clip(round2s(gv, 5))
					}
				} else if i < 1 && ln > 0 && g.overlap {
					old := stripes[ln-1][p][(i+16)*sw+x]
					gv = clip(round2s(old*23+gv*22, 5))
				}
				noise[p][y*pw+x] = gv
			}
		}
	}

	// Blend.
	var minV, maxLuma, maxChroma int32
	if g.clipRestricted {
		minV = 16 << (bd - 8)
		maxLuma = 235 << (bd - 8)
		maxChroma = 240 << (bd - 8)
		if s.MatrixCoeffs == 0 {
			maxChroma = maxLuma
		}
	} else {
		maxLuma = 256<<(bd-8) - 1
		maxChroma = maxLuma
	}
	scalingShift := uint(g.scalingShift)
	maxPix := int32(1)<<bd - 1
	yp := &out.planes[0]
	if f.numPlanes > 1 {
		cw, ch := (w+int(subX))>>subX, (h+int(subY))>>subY
		for c := 1; c <= 2; c++ {
			num, mult, lumaMult, offset := g.numCb, g.cbMult, g.cbLumaMult, g.cbOffset
			if c == 2 {
				num, mult, lumaMult, offset = g.numCr, g.crMult, g.crLumaMult, g.crOffset
			}
			if num == 0 && !g.chromaScalingFromLuma {
				continue
			}
			pb := &out.planes[c]
			for y := 0; y < ch; y++ {
				for x := 0; x < cw; x++ {
					lx, ly := x<<subX, y<<subY
					lnx := min(lx+1, w-1)
					avg := yp.get(lx, ly)
					if subX != 0 {
						avg = (yp.get(lx, ly) + yp.get(lnx, ly) + 1) >> 1
					}
					orig := pb.get(x, y)
					merged := avg
					if !g.chromaScalingFromLuma {
						comb := avg*int32(lumaMult-128) + orig*int32(mult-128)
						merged = min(max(comb>>6+int32(offset-256)<<(bd-8), 0), maxPix)
					}
					nv := round2s(scaleLut(c, merged)*noise[c][y*cw+x], scalingShift)
					pb.set(x, y, min(max(orig+nv, minV), maxChroma))
				}
			}
		}
	}
	if g.numY > 0 {
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				orig := yp.get(x, y)
				nv := round2s(scaleLut(0, orig)*noise[0][y*w+x], scalingShift)
				yp.set(x, y, min(max(orig+nv, minV), maxLuma))
			}
		}
	}
	return out
}
